  describe("Reglas de la tienda", () => {
    let data2;
    const customer = {
      name: "Cliente",
      lastName: "Prueba",
      email: "cliente@example.com",
      street: "Calle 1",
      city: "Santiago",
      region: "Metropolitana",
      delivery: "Retiro en tienda"
    };
    beforeEach(() => {
      data2 = initialData();
    });
    it("calcula descuentos", () => {
      expect(discountedPrice({ price: 1e4, discount: 20 })).toBe(8e3);
    });
    it("agrega un producto sin modificar el estado anterior", () => {
      const next = actions.addToCart(data2, 1);
      expect(next.cart).toEqual([{ productId: 1, quantity: 1 }]);
      expect(data2.cart).toEqual([]);
    });
    it("suma unidades del mismo producto", () => {
      const next = actions.addToCart(actions.addToCart(data2, 1), 1);
      expect(next.cart.length).toBe(1);
      expect(next.cart[0].quantity).toBe(2);
    });
    it("rechaza cantidades mayores al stock", () => {
      expect(() => actions.addToCart(data2, 1, 999)).toThrowError(/stock/);
    });
    it("rechaza cantidades decimales", () => {
      expect(() => actions.addToCart(data2, 1, 1.5)).toThrowError(/entero/);
    });
    it("elimina la l\xEDnea cuando la cantidad es cero", () => {
      expect(
        actions.changeQuantity(actions.addToCart(data2, 1), 1, 0).cart
      ).toEqual([]);
    });
    it("calcula el total con cantidad y descuento", () => {
      expect(cartTotal(actions.addToCart(data2, 1, 2))).toBe(
        discountedPrice(data2.products[0]) * 2
      );
    });
    it("rechaza un precio inv\xE1lido", () => {
      const product = structuredClone(data2.products[0]);
      product.price = -1;
      expect(() => actions.saveProduct(data2, product)).toThrowError(/Precio/);
    });
    it("crea, edita y elimina un producto", () => {
      const newProduct = structuredClone(data2.products[0]);
      newProduct.name = "Producto nuevo";
      const created = actions.saveProduct(data2, newProduct);
      const id = created.products.at(-1).id;
      const editedProduct = structuredClone(created.products.at(-1));
      editedProduct.name = "Nombre editado";
      const edited = actions.saveProduct(created, editedProduct, id);
      expect(edited.products.at(-1).name).toBe("Nombre editado");
      expect(actions.deleteProduct(edited, id).products.length).toBe(
        data2.products.length
      );
    });
    it("protege los productos que est\xE1n en el carrito", () => {
      expect(
        () => actions.deleteProduct(actions.addToCart(data2, 1), 1)
      ).toThrowError(/carrito/);
    });
    it("renombra la categor\xEDa tambi\xE9n en los productos", () => {
      const oldName = data2.products[0].category;
      expect(
        actions.saveCategory(data2, "Nueva categor\xEDa", oldName).products[0].category
      ).toBe("Nueva categor\xEDa");
    });
    it("impide categor\xEDas duplicadas", () => {
      expect(() => actions.saveCategory(data2, data2.categories[0])).toThrowError(
        /existe/
      );
    });
    it("impide correos duplicados", () => {
      expect(
        () => actions.saveUser(data2, { name: "Duplicado", email: data2.users[0].email })
      ).toThrowError(/registrado/);
    });
    it("rechaza un correo inv\xE1lido", () => {
      expect(
        () => actions.saveUser(data2, { name: "Cliente", email: "incorrecto" })
      ).toThrowError(/inválido/);
    });
    it("no acepta pedidos vac\xEDos", () => {
      expect(() => actions.placeOrder(data2, customer)).toThrowError(/vacío/);
    });
    it("un pago exitoso descuenta stock y vac\xEDa el carrito", () => {
      const next = actions.placeOrder(actions.addToCart(data2, 1, 2), customer);
      expect(next.orders[0].status).toBe("pagado");
      expect(next.products[0].stock).toBe(data2.products[0].stock - 2);
      expect(next.cart).toEqual([]);
    });
    it("un pago rechazado conserva stock y carrito", () => {
      const next = actions.placeOrder(actions.addToCart(data2, 1), customer, {
        simulateFailure: true
      });
      expect(next.orders[0].status).toBe("rechazado");
      expect(next.products[0].stock).toBe(data2.products[0].stock);
      expect(next.cart.length).toBe(1);
    });
  });

